// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address admin, address proposedOwner) public {
        vm.assume(admin != address(0));
        vm.assume(proposedOwner != address(0));
        Forwarder f = new Forwarder();

        vm.deal(address(f), 1 ether);

        bool ok;
        try c.setOwner(proposedOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.owner() == proposedOwner);
    }
}

contract Forwarder {
    function forward(address target, bytes calldata data) external payable returns (bool, bytes memory) {
        (bool success, bytes memory ret) = target.call{value: msg.value}(data);
        return (success, ret);
    }
}
